<template>
  <div class="space-y-6"><header><p class="text-xs font-bold uppercase tracking-[.18em] text-brand-strong">Circuit de validation</p><h1 class="mt-1 text-2xl font-bold text-main">Approbations en attente</h1><p class="mt-1 text-xs text-secondary-custom">Chaque décision est tracée; l’auto-approbation et les décisions répétées sont bloquées côté serveur.</p></header><div v-if="error" role="alert" class="rounded-card border border-rose-500/30 bg-rose-500/10 p-4 text-xs font-semibold text-rose-700 dark:text-rose-300">{{ error }}</div><AppTable :empty="!loading && !pending.length"><template #header><tr><th class="px-5 py-4">Collaborateur</th><th class="px-5 py-4">Demande</th><th class="px-5 py-4">Période</th><th class="px-5 py-4">Statut</th><th class="px-5 py-4 text-right">Action</th></tr></template><tr v-if="loading"><td colspan="5" class="p-12 text-center text-muted-custom">Chargement…</td></tr><tr v-for="item in pending" :key="item.id" class="hover:bg-surface-hover"><td class="px-5 py-4 font-bold text-main">{{ item.employee.displayName }}</td><td class="px-5 py-4 font-mono text-xs">{{ item.requestNumber }}</td><td class="px-5 py-4 text-xs">{{ date(item.startDate) }} → {{ date(item.endDate) }}</td><td class="px-5 py-4"><AppStatusBadge :status="item.status" /></td><td class="px-5 py-4 text-right"><NuxtLink :to="`/rh/conges/${item.id}`" class="rounded-control border border-custom px-3 py-2 text-xs font-bold text-brand-strong">Examiner</NuxtLink></td></tr><template #empty><p>Aucune décision n’est en attente.</p></template></AppTable></div>
</template>
<script setup lang="ts">
import AppTable from '~/components/ui/AppTable.vue'; import AppStatusBadge from '~/components/ui/AppStatusBadge.vue'
useHead({ title: 'Approbations de congés' }); definePageMeta({ middleware: 'auth' })
const { requests, loading, error, fetchRequests } = useHrLeave(); const pending = computed(() => requests.value.filter(item => ['SUBMITTED', 'PENDING_APPROVAL', 'PENDING_MANAGER', 'PENDING_HR', 'CANCEL_REQUESTED'].includes(item.status))); const date = (value: string) => new Intl.DateTimeFormat('fr-FR', { dateStyle: 'medium', timeZone: 'UTC' }).format(new Date(value)); onMounted(() => fetchRequests().catch(() => undefined))
</script>
